n0:createOraclePackageSpec.n0:source:
CREATE OR REPLACE EDITIONABLE PACKAGE "%USER_NAME%"."SURVEY_RULES" as
    -- business rules
    months_between_surveys number := 6;
    days_before_survey_warning number := 14;

    function days_to_next_survey(p_case_number in number) return number;
    function last_survey(p_case_number in number) return date;
    function next_survey(p_case_number in number) return date;
end survey_rules;
/
